import React, { useState, useEffect } from 'react';
import axios from 'axios';

function Posts({ searchQuery = "", selectedCategory = "ALL" }) {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  const userString = localStorage.getItem('user');
  const currentUser = userString ? JSON.parse(userString) : null;
  const currentUserId = currentUser ? (currentUser._id || currentUser.id || currentUser.email || currentUser.name) : null;

  useEffect(() => {
    const fetchPosts = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/posts');
        setPosts(response.data);
      } catch (error) {
        console.error('Error fetching posts from MongoDB:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchPosts();
  }, []);

  const handleDelete = async (postId) => {
    if (!window.confirm("Remove this listing from Thrift Shop?")) return;
    try {
      await axios.delete(`http://localhost:5000/api/posts/${postId}`);
      setPosts((prevPosts) => prevPosts.filter((post) => post._id !== postId));
    } catch (error) {
      console.error('Error deleting post:', error);
      alert('Failed to delete post.');
    }
  };

  // Filter posts by search bar text and selected category
  const filteredPosts = posts.filter((post) => {
    const titleText = (post.title || post.name || "").toLowerCase();
    const descText = (post.description || "").toLowerCase();
    const categoryText = (post.category || "").toLowerCase();
    const query = searchQuery.toLowerCase().trim();

    const matchesSearch =
      !query ||
      titleText.includes(query) ||
      descText.includes(query) ||
      categoryText.includes(query);

    const matchesCategory =
      selectedCategory === "ALL" ||
      (post.category && post.category.toLowerCase() === selectedCategory.toLowerCase());

    return matchesSearch && matchesCategory;
  });

  const formatDate = (dateString) => {
    if (!dateString) return "Just now";
    const date = new Date(dateString);
    return date.toLocaleDateString('en-IN', { day: '2-digit', month: 'short' });
  };

  // Helper to get whichever image field is saved in MongoDB
  const getPostImage = (post) => {
    return (
      post.image ||
      post.imageUrl ||
      post.url ||
      post.photo ||
      post.img ||
      (Array.isArray(post.images) && post.images[0]) ||
      ""
    );
  };

  return (
    <div style={{ padding: '25px 20px', maxWidth: '1200px', margin: '0 auto' }}>
      <h2 style={{ color: '#002f34', marginBottom: '20px' }}>Fresh Recommendations</h2>

      {loading ? (
        <p style={{ textAlign: 'center', fontSize: '16px', color: '#555' }}>Loading products...</p>
      ) : filteredPosts.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px 20px', color: '#555' }}>
          <h3>No products found</h3>
          <p>Try clearing your search filter or click "+ SELL" to list a new product.</p>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '20px' }}>
          {filteredPosts.map((post) => {
            const imgSrc = getPostImage(post);
            const isOwner = currentUser && (post.sellerId === currentUserId || post.userId === currentUserId || post.sellerName === currentUser.name);

            return (
              <div
                key={post._id}
                style={{
                  border: '1px solid #ddd',
                  borderRadius: '6px',
                  padding: '12px',
                  backgroundColor: '#fff',
                  boxShadow: '0 1px 4px rgba(0,0,0,0.06)',
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'space-between',
                  position: 'relative'
                }}
              >
                <div>
                  <div style={{ width: '100%', height: '200px', backgroundColor: '#f0f0f0', borderRadius: '4px', overflow: 'hidden', marginBottom: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    {imgSrc ? (
                      <img
                        src={imgSrc}
                        alt={post.title || post.name}
                        style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      />
                    ) : (
                      <span style={{ color: '#888' }}>No Image</span>
                    )}
                  </div>

                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h3 style={{ margin: '0 0 6px 0', color: '#002f34', fontSize: '20px' }}>
                      ₹ {Number(post.price).toLocaleString('en-IN')}
                    </h3>

                    {isOwner && (
                      <button
                        onClick={() => handleDelete(post._id)}
                        title="Delete Listing"
                        style={{
                          backgroundColor: '#ffeded',
                          color: '#d9534f',
                          border: '1px solid #f5c2c7',
                          borderRadius: '4px',
                          padding: '3px 8px',
                          fontSize: '12px',
                          cursor: 'pointer',
                          fontWeight: 'bold'
                        }}
                      >
                        Delete
                      </button>
                    )}
                  </div>

                  <p style={{ margin: '0 0 4px 0', fontWeight: 'bold', color: '#333', fontSize: '15px' }}>
                    {post.title || post.name}
                  </p>

                  {post.category && (
                    <span style={{ display: 'inline-block', fontSize: '12px', backgroundColor: '#eef3f4', color: '#002f34', padding: '2px 8px', borderRadius: '10px', marginBottom: '8px' }}>
                      {post.category}
                    </span>
                  )}
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: '#777', marginTop: '12px', paddingTop: '8px', borderTop: '1px solid #f0f0f0' }}>
                  <span>{post.location || 'India'}</span>
                  <span>{formatDate(post.createdAt)}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default Posts;
